package main

import "html/template"

var contextSearchPageTemplate = template.Must(template.New("context-search").Parse(`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Search · {{.Name}} · Trace</title><link rel="icon" href="/assets/trace-mark.svg?v=4" type="image/svg+xml">` + pageStyle + `<style>
.search-wrap{max-width:1040px;margin:0 auto}.search-intro{padding:18px 0 10px}.search-intro h1{font-size:clamp(34px,5vw,52px);line-height:1.05}.search-intro p{max-width:660px;margin:.5rem 0 0}.search-form{display:grid;grid-template-columns:minmax(0,1fr) 150px 170px auto;gap:10px;align-items:end}.search-form label{display:block;margin:0;color:var(--text);font-size:12px;font-weight:700}.search-form input,.search-form select{display:block;width:100%;height:42px;min-width:0;margin:7px 0 0;padding:8px 11px;border:1px solid var(--line);border-radius:8px;background:var(--bg);color:var(--text)}.search-form button{height:42px;margin:0;padding:0 18px;border-color:var(--accent);background:var(--accent);color:#052827}.search-form button:hover{background:var(--lime)}.search-results{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;align-items:start}.search-results.single{grid-template-columns:1fr}.search-results section{min-width:0;margin-top:18px}.search-results h2{display:flex;justify-content:space-between;align-items:center;gap:10px}.search-results h2 span{font-size:12px;font-weight:600;color:var(--muted)}.search-hit{padding:14px 0;border-top:1px solid var(--line)}.search-hit:first-of-type{margin-top:15px}.search-hit a{font-weight:700;text-decoration:none;overflow-wrap:anywhere}.search-hit a:hover{text-decoration:underline}.search-hit p{margin:5px 0 0;font-size:12px}.search-hit pre{margin:10px 0 0;max-height:150px;overflow:auto;border-color:var(--line);background:var(--bg);color:var(--text)}.search-empty{padding:16px 0}.search-error{border-color:#a94d53;color:#ffdfe0}html[data-theme="light"] .search-error{color:#842c33}html[data-theme="light"] .search-form input,html[data-theme="light"] .search-form select{background:#fff}html[data-theme="light"] .search-form button{background:var(--accent);border-color:var(--accent);color:#fff}html[data-theme="light"] .search-form button:hover{background:#006c66}@media(max-width:760px){.search-form{grid-template-columns:1fr 1fr}.search-form label:first-child{grid-column:1/-1}.search-form button{width:100%}.search-results{grid-template-columns:1fr}}@media(max-width:480px){.search-form{grid-template-columns:1fr}.search-form label:first-child{grid-column:auto}}
</style></head><body><div class="search-wrap"><div class="repo-nav"><a href="/repos/{{.Name}}"><img src="/assets/trace-mark.svg?v=4" alt="" width="38" height="38">Trace</a><a href="/repos/{{.Name}}">← {{.Name}}</a></div><div class="search-intro"><h1>Search code and context.</h1><p>Find literal text in code, commit history, and structured agent checkpoints on the selected branch.</p></div><section><form class="search-form" method="get" action="/repos/{{.Name}}/search"><label>Search query<input name="q" value="{{.Query}}" required maxlength="200" autocomplete="off" placeholder="Function, decision, or commit"></label><label>Branch<input name="ref" value="{{.Ref}}" placeholder="main"></label><label>Scope<select name="scope"><option value="all"{{if eq .Scope "all"}} selected{{end}}>All sources</option><option value="code"{{if eq .Scope "code"}} selected{{end}}>Code only</option><option value="commits"{{if eq .Scope "commits"}} selected{{end}}>Commits only</option><option value="sessions"{{if eq .Scope "sessions"}} selected{{end}}>Sessions only</option></select></label><button type="submit">Search</button></form></section>{{if .Error}}<section class="search-error" role="alert">{{.Error}}</section>{{end}}{{if and .Query (not .Error)}}<div class="search-results{{if ne .Scope "all"}} single{{end}}">{{if or (eq .Scope "all") (eq .Scope "code")}}<section><h2>Code <span>{{len .Results}} matches</span></h2>{{range .Results}}<article class="search-hit"><a href="/repos/{{$.Name}}?branch={{urlquery $.Ref}}&amp;file={{urlquery .Path}}">{{.Path}}:{{.Line}}</a><pre>{{.Content}}</pre></article>{{else}}<p class="search-empty muted">No matching code on {{.Ref}}.</p>{{end}}{{if .Truncated}}<p class="muted">Showing the first 100 code matches.</p>{{end}}</section>{{end}}{{if or (eq .Scope "all") (eq .Scope "commits")}}<section class="commit-section"><h2>Commits <span>{{len .Commits}} matches</span></h2>{{range .Commits}}<article class="search-hit"><a href="/repos/{{$.Name}}/commits/{{.Commit}}?ref={{urlquery $.Ref}}">{{.Subject}}</a><p><code>{{printf "%.12s" .Commit}}</code> · {{.Author}}</p></article>{{else}}<p class="search-empty muted">No matching commits on {{.Ref}}.</p>{{end}}{{if .CommitsTruncated}}<p class="muted">Commit search is limited to the newest 1,000 commits and 100 matches.</p>{{end}}</section>{{end}}{{if or (eq .Scope "all") (eq .Scope "sessions")}}<section><h2>Agent sessions <span>{{len .Sessions}} matches</span></h2>{{range .Sessions}}<article class="search-hit"><a href="/repos/{{$.Name}}/agents#session-{{.SessionID}}">{{.Agent}} · session #{{.SessionID}}{{if .CheckpointID}} · checkpoint #{{.CheckpointID}}{{end}}</a><p>{{.Source}} · <code>{{.Commit}}</code></p>{{if .Excerpt}}<pre>{{.Excerpt}}</pre>{{end}}</article>{{else}}<p class="search-empty muted">No matching agent sessions.</p>{{end}}{{if .SessionsTruncated}}<p class="muted">Showing the first 100 session matches.</p>{{end}}</section>{{end}}</div>{{end}}</div></body></html>`))
